var a=[{title:`Läs förhållandet`,text:`Ett 1:3-intervall kan vara 20 sekunders ansträngning och 60 sekunders återhämtning, ett 1:1-intervall kan vara 30 sekunder av varje, och 2:1 kan vara 40 sekunders arbete och 20 sekunders lugn. Förhållandet ensamt beskriver inte passet förrän du känner till varaktighet och intensitet.`},{title:`Lång återhämtning för kvalitet`,text:`Ganska lång vila hjälper dig att behålla fart eller kraft genom korta hårda insatser. Ett 1:3-upplägg kan passa någon som övar snabbare löpning eller en krävande rörelse och vill undvika att bli trött direkt. Mycket intensiv sprint kan behöva mycket mer återhämtning än 1:3 för att hålla uppe effekten.`},{title:`Lika lång eller kort återhämtning`,text:`Vid 1:1 tar arbete och återhämtning lika lång tid. Vid 2:1 är återhämtningen kortare, så tröttheten kan byggas upp snabbt. De här formaten kan fungera för måttliga cirklar, men de är inte automatiskt bättre för avancerade uthållighets- eller styrkemål.`},{title:`Anpassa efter förmåga och övning`,text:`En nybörjare kan gå raskt i 30 sekunder och lugnt i 90 sekunder och sedan långsamt förlänga arbetet. En tränad cyklist kan använda längre hårda insatser med generös återhämtning. Hoppande rörelser kräver ofta mer teknisk kontroll, så välj vila som håller dina landningar bra. Bedöm framsteg efter om du avslutar med bra teknik, förläng vilan när du behöver det och gör inte varje intervall hårdare bara för att korta ner passet.`}];var r=[{label:`ACE: utforma högintensiva intervaller`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: mäta aktivitetsintensitet och pratprovet`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: rekommendationer om fysisk aktivitet för vuxna`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var n={sections:a,sources:r};export{n as default,a as sections,r as sources};